css:
/* Modales (Login & Perfil B2B) */
.saas-modal-overlay { position: fixed; inset: 0; background: rgba(10, 34, 64, 0.6); backdrop-filter: blur(5px); z-index: 3000; display: flex; align-items: center; justify-content: center; padding: 20px; opacity: 1; transition: opacity 0.3s ease; }
.saas-modal-overlay.hidden { opacity: 0; pointer-events: none; }
.saas-modal-card { background: #FFFFFF; width: 100%; max-width: 440px; border-radius: 24px; padding: 40px; box-shadow: 0 25px 50px -12px rgba(0,0,0,0.25); position: relative; transform: translateY(0); transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1); border: 1px solid #E2E8F0; }
.saas-modal-overlay.hidden .saas-modal-card { transform: translateY(30px); }

.close-modal-btn { position: absolute; top: 20px; right: 20px; background: transparent; border: none; font-size: 1.8rem; color: #94a3b8; cursor: pointer; transition: color 0.2s; line-height: 1; width: 30px; height: 30px; display: flex; align-items: center; justify-content: center; border-radius: 50%; }
.close-modal-btn:hover { color: #A81200; background: #fef2f2; }

/* Login Modal */
.modal-header-center { text-align: center; margin-bottom: 20px; }
.modal-logo-clean { height: 75px; margin-bottom: 15px; object-fit: contain; }
.modal-header-center h2 { font-size: 1.8rem; font-weight: 900; color: #0A2240; margin-bottom: 10px; letter-spacing: -0.5px; }
.modal-header-center p { font-size: 0.95rem; color: #64748B; line-height: 1.5; }
.secure-badge { display: flex; justify-content: center; align-items: center; gap: 6px; margin-top: 25px; font-size: 0.8rem; color: #94a3b8; font-weight: 600; }
.secure-badge svg { width: 14px; height: 14px; }

/* Perfil B2B Modal */
.profile-card { max-width: 480px; padding: 0; overflow: hidden;}
.profile-header { background: #f8fafc; padding: 30px; display: flex; align-items: center; gap: 20px; border-bottom: 1px solid #E2E8F0; }
.profile-avatar-img { width: 64px; height: 64px; border-radius: 50%; object-fit: cover; box-shadow: 0 4px 10px rgba(10,34,64,0.1); border: 2px solid #FFFFFF; background: #E2E8F0;}
.profile-info h2 { font-size: 1.25rem; font-weight: 800; color: #0F172A; margin-bottom: 2px; line-height: 1.2; word-break: break-word;}
.user-email { font-size: 0.9rem; color: #64748b; font-weight: 500; }

.reorder-section { padding: 30px; }
.reorder-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px; }
.reorder-header h3 { font-size: 1.05rem; font-weight: 800; color: #0A2240; text-transform: uppercase; }

.order-list-preview { background: #f8fafc; border: 1px solid #E2E8F0; border-radius: 12px; padding: 15px 20px; margin-bottom: 25px; }
.order-list-preview ul { list-style: none; display: flex; flex-direction: column; gap: 8px; padding: 0; margin: 0; }
.order-list-preview li { display: flex; align-items: center; gap: 8px; font-size: 0.95rem; color: #0F172A; font-weight: 500; }
.order-list-preview li svg { width: 16px; color: #10b981; }

.logout-wrapper { padding: 0 30px 25px; display: flex; justify-content: center; }
.btn-logout { background: transparent; border: none; color: #94a3b8; font-size: 0.9rem; font-weight: 600; cursor: pointer; text-decoration: underline; transition: color 0.2s;}
.btn-logout:hover { color: #A81200; }

/* Icono Navbar Logueado Global */
.icon-btn.logged-in { border-color: #25D366 !important; background: rgba(37, 211, 102, 0.1) !important; position: relative; }
.icon-btn.logged-in::after { content: ''; position: absolute; top: 0px; right: 0px; width: 12px; height: 12px; background: #25D366; border-radius: 50%; border: 2px solid #16365C; z-index: 2;}
.nav-user-avatar { width: 100%; height: 100%; object-fit: cover; border-radius: 50%; display: none; }
.icon-btn.logged-in .nav-user-avatar { display: block; }
.icon-btn.logged-in svg { display: none; }

/* Toasts Globales */
.toast-container { position: fixed; bottom: 100px; left: 50%; transform: translateX(-50%); z-index: 3000; display: flex; flex-direction: column; gap: 10px; pointer-events: none; }
.toast { background: rgba(10, 34, 64, 0.95); backdrop-filter: blur(10px); color: #FFFFFF; padding: 14px 28px; border-radius: 50px; font-size: 0.95rem; font-weight: 600; box-shadow: 0 10px 30px rgba(0,0,0,0.3); display: flex; align-items: center; gap: 12px; animation: toastSlideUp 0.3s ease forwards; border: 1px solid rgba(255,255,255,0.1); }
.toast svg { width: 20px; color: #25D366; }
.toast.fade-out { animation: toastFadeOut 0.4s ease forwards; }
@keyframes toastSlideUp { from { opacity: 0; transform: translateY(30px) scale(0.9); } to { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes toastFadeOut { to { opacity: 0; transform: translateY(-15px) scale(0.9); } }


/* =========================================
   1. VARIABLES Y BASE
   ========================================= */
:root {
    --zarco-blue: #0A2240; 
    --zarco-blue-light: #16365C; 
    --zarco-blue-glass: rgba(10, 34, 64, 0.95); 
    --zarco-red: #A81200; 
    --zarco-red-dark: #7A0A00; 
    --white: #FFFFFF; 
    --wa-green: #25D366; 
    --transition-fast: 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
    --expo: cubic-bezier(0.16, 1, 0.3, 1);
}

* { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html { scroll-behavior: smooth; }
body { font-family: 'Inter', sans-serif; background-color: var(--white); color: var(--zarco-blue); overflow-x: hidden; }

.desktop-only { display: block; }
.mobile-only { display: none; }

/* REVEAL ENGINE FLUIDO */
.reveal { opacity: 0; transform: translateY(30px); transition: 1.2s var(--expo); will-change: opacity, transform; }
.reveal.active { opacity: 1; transform: translateY(0); }
.stagger-1 { transition-delay: 0.1s; } 
.stagger-2 { transition-delay: 0.2s; } 
.stagger-3 { transition-delay: 0.3s; }

/* =========================================
   2. BANNERS PRINCIPALES (SLIDERS)
   ========================================= */
.hero-slider { position: relative; width: 100%; background-color: var(--white); overflow: hidden; }
/* Margen ajustado asumiendo Navbar global */
.main-slider { margin-top: 185px; } 

.slider-wrapper { display: flex; width: 100%; transition: transform 0.8s var(--expo); }
.slide { flex: 0 0 100%; min-width: 100%; position: relative; display: block; }
.slide picture { display: block; width: 100%; height: auto; }
.slide img { width: 100%; height: auto; display: block; object-fit: cover; }

.slider-arrow { position: absolute; top: 50%; transform: translateY(-50%); background: rgba(10, 34, 64, 0.3); backdrop-filter: blur(8px); border: 1px solid rgba(255,255,255,0.2); color: var(--white); width: 50px; height: 50px; font-size: 20px; cursor: pointer; border-radius: 50%; display: flex; align-items: center; justify-content: center; z-index: 10; transition: all var(--transition-fast); }
.slider-arrow:hover { background: var(--zarco-blue); transform: translateY(-50%) scale(1.1); }
.slider-arrow.prev { left: 30px; }
.slider-arrow.next { right: 30px; }
.slider-dots { position: absolute; bottom: 20px; width: 100%; display: flex; justify-content: center; gap: 10px; z-index: 10; }
.dot { width: 10px; height: 10px; background: rgba(255, 255, 255, 0.5); border: 2px solid var(--white); border-radius: 50%; cursor: pointer; transition: all var(--transition-fast); }
.dot.active { background: var(--zarco-red); border-color: var(--zarco-red); transform: scale(1.3); }

/* =========================================
   3. CINTA DE MARCAS (MARQUEE) - MEJORADA
   ========================================= */
.marquee-section {
    width: 100%;
    overflow: hidden;
    background-color: #FFFFFF; 
    margin: 30px 0 0; 
}
.marquee-title {
    color: var(--zarco-blue);
    font-size: 1.8rem;
    font-weight: 900;
    letter-spacing: -0.5px;
    margin-bottom: 20px;
    text-transform: uppercase;
    text-align: center;
}

/* Modificación: Se quitaron los bordes para un look más infinito */
.marquee-wrapper-img {
    width: 100%;
    overflow: hidden;
    background: transparent;
    padding: 35px 0;
}

.marquee-wrapper-img:hover .marquee-track-img {
    -webkit-animation-play-state: paused;
    animation-play-state: paused;
}

.marquee-track-img {
    display: flex;
    align-items: center;
    width: max-content; 
    -webkit-animation: marqueeScroll 45s linear infinite;
    animation: marqueeScroll 45s linear infinite;
    will-change: transform;
}

.marquee-group-img {
    display: flex;
    flex-shrink: 0; 
    align-items: center;
    gap: 90px; /* Separación ampliada */
    padding-right: 90px; 
}

/* Modificación: Logos más grandes */
.brand-logo-img {
    height: 95px; 
    width: auto;
    max-width: 300px; 
    object-fit: contain;
    display: block;
    flex-shrink: 0;
    transition: transform 0.3s ease;
}
.brand-logo-img:hover {
    transform: scale(1.08);
}

/* Modificación: Usar translate3d para fluidez extrema (GPU) */
@-webkit-keyframes marqueeScroll {
    0% { -webkit-transform: translate3d(0, 0, 0); transform: translate3d(0, 0, 0); }
    100% { -webkit-transform: translate3d(-50%, 0, 0); transform: translate3d(-50%, 0, 0); } 
}
@keyframes marqueeScroll {
    0% { transform: translate3d(0, 0, 0); }
    100% { transform: translate3d(-50%, 0, 0); } 
}

/* =========================================
   4. TARJETAS DE LÍNEAS DE NEGOCIO 
   ========================================= */
.hero-categories { padding: 10px 5% 40px; background-color: var(--white); display: flex; flex-direction: column; align-items: center; overflow: hidden; }
.section-header { text-align: center; margin-bottom: 3.5rem; }
.section-header h1 { color: var(--zarco-blue); font-size: 3rem; font-weight: 900; letter-spacing: -1px; margin-bottom: 1rem; }
.section-header p { color: #666; font-size: 1.1rem; max-width: 700px; margin: 0 auto; }

.swipe-hint { display: none; }

.cards-container { display: flex; gap: 2rem; width: 100%; max-width: 1400px; }
.category-card { flex: 1; position: relative; height: 500px; border-radius: 12px; overflow: hidden; cursor: pointer; box-shadow: 0 8px 25px rgba(0,0,0,0.06); transition: transform 0.6s var(--expo), box-shadow 0.6s var(--expo); display: flex; flex-direction: column; justify-content: flex-end; text-decoration: none; }
.card-bg { position: absolute; inset: 0; background: #eee; transition: transform 1s var(--expo); z-index: 1; background-size: cover; background-position: center; }
.card-overlay { position: absolute; bottom: 0; left: 0; width: 100%; height: 80%; background: linear-gradient(to top, rgba(10, 34, 64, 0.95) 0%, rgba(10, 34, 64, 0.5) 40%, rgba(10, 34, 64, 0) 100%); z-index: 2; transition: height 0.6s var(--expo); }
.card-content { position: relative; padding: 35px 25px; z-index: 3; }
.card-title { color: var(--white); font-size: 2rem; font-weight: 900; margin-bottom: 12px; transition: transform 0.6s var(--expo); }
.card-desc { color: rgba(255, 255, 255, 0.85); font-size: 0.95rem; line-height: 1.5; margin-bottom: 0; }

.card-action { 
    display: inline-flex; 
    align-items: center; 
    background: rgba(255,255,255,0.95); 
    color: var(--zarco-blue); 
    padding: 12px 25px;
    border-radius: 50px;
    font-weight: 800; 
    font-size: 0.85rem; 
    margin-top: 20px; 
    text-transform: uppercase; 
    letter-spacing: 1px; 
    opacity: 0; 
    transform: translateY(15px); 
    transition: all 0.4s var(--expo); 
    box-shadow: 0 4px 15px rgba(0,0,0,0.2);
}
.card-action span { margin-left: 8px; transition: transform var(--transition-fast); }

.category-card:hover { transform: translateY(-10px); box-shadow: 0 20px 40px rgba(10, 34, 64, 0.15); }
.category-card:hover .card-bg { transform: scale(1.05); }
.category-card:hover .card-overlay { height: 100%; }
.category-card:hover .card-title, .category-card:hover .card-desc { transform: translateY(-5px); }
.category-card:hover .card-action { opacity: 1; transform: translateY(0); background: var(--zarco-red); color: var(--white); }

/* Fondos Tarjetas Sector */
.restaurant-card .card-bg { background-image: url('/assets/69ac7eba05dea11f5c5cb6bf_Diseno-sin-titulo.webp'); background-size: cover; background-position: center; background-repeat: no-repeat; inset: 0; }
.tienda-card .card-bg { background-image: url('/assets/69ac89a8760a05cf8dd617ac_Diseno-sin-titulo-2.webp'); background-size: cover; background-position: center; background-repeat: no-repeat; inset: 0; }
.cafeteria-card .card-bg { background-image: url('/assets/69ac80f7994d44765138aece_Diseno-sin-titulo-1.webp'); background-size: cover; background-position: center; background-repeat: no-repeat; inset: 0; }

/* =========================================
   5. FAMILIAS DE PRODUCTOS
   ========================================= */
.product-categories-section { padding: 40px 5% 40px; background-color: var(--white); display: flex; flex-direction: column; align-items: center; overflow: hidden; }

.prod-cats-container { 
    display: grid; 
    grid-template-columns: repeat(3, 1fr); 
    gap: 2rem; 
    width: 100%; 
    max-width: 1400px; 
}

.prod-cat-card { 
    display: flex; 
    flex-direction: column; 
    align-items: center; 
    text-decoration: none; 
    cursor: pointer;
    gap: 8px; 
}

.prod-cat-img-wrapper {
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    background: transparent; 
    box-shadow: none; 
    margin-bottom: 0; 
    transition: transform 0.4s var(--expo);
}

.prod-cat-img-wrapper img {
    width: 100%;
    max-width: 280px; 
    height: auto;
    object-fit: contain;
    display: block;
    transition: transform 0.4s var(--expo), filter 0.4s ease;
    filter: drop-shadow(0 10px 20px rgba(0,0,0,0.08)); 
}

.prod-cat-card:hover .prod-cat-img-wrapper img { 
    transform: translateY(-10px) scale(1.05); 
    filter: drop-shadow(0 15px 25px rgba(0,0,0,0.15)); 
}

.prod-cat-title {
    color: var(--zarco-blue);
    font-size: 1.25rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    transition: color var(--transition-fast);
    text-align: center;
    margin-top: 0;
}
.prod-cat-card:hover .prod-cat-title { color: var(--zarco-red); }

/* =========================================
   6. LÍDERES QUE CONFÍAN
   ========================================= */
.brands-section { padding: 60px 5%; background-color: var(--white); display: flex; flex-direction: column; align-items: center; overflow: hidden; }
.brands-header { margin-bottom: 3rem; text-align: center; }
.brands-title { color: var(--zarco-blue); font-size: 2rem; font-weight: 900; letter-spacing: 1px; text-transform: uppercase; }

.brands-container.grid-4x2 { 
    display: grid; 
    grid-template-columns: repeat(4, 1fr); 
    gap: 30px; 
    width: 100%; 
    max-width: 1400px; 
    justify-content: center; 
}

.grid-4x2 .brand-card { 
    background: transparent;
    border: none;
    padding: 0;
    display: flex; 
    align-items: center; 
    justify-content: center;
}
.grid-4x2 .brand-card img { 
    width: 100%; 
    max-width: 280px;
    height: auto; 
    object-fit: contain; 
    border-radius: 10px;
    display: block; 
    transition: transform 0.3s ease; 
}
.grid-4x2 .brand-card:hover img { 
    transform: scale(1.05);
}

/* =========================================
   7. BANNERS SECUNDARIOS
   ========================================= */
.secondary-slider { margin-top: 40px; margin-bottom: 80px; }

/* =========================================
   8. RESPONSIVIDAD MÓVIL
   ========================================= */
@media (max-width: 1024px) {
    .desktop-only { display: none !important; }
    .mobile-only { display: flex !important; }

    .main-slider { margin-top: 130px; } 
    .slider-arrow { display: none !important; }

    .marquee-title { font-size: 1.4rem; margin-bottom: 20px; }

    .marquee-wrapper-img { padding: 25px 0; }
    .marquee-group-img { gap: 50px; padding-right: 50px; }

    /* Logos ajustados y crecidos para móvil */
    .brand-logo-img { height: 60px; max-width: 180px; } 

    .hero-categories { padding: 10px 0 30px; } 
    .section-header { padding: 0 5%; }
    .section-header h1 { font-size: 2.2rem; }

    .swipe-hint {
        display: flex !important; 
        justify-content: center;
        align-items: center;
        gap: 8px;
        font-size: 0.8rem;
        font-weight: 800;
        color: #64748B;
        text-transform: uppercase;
        letter-spacing: 1.5px;
        margin-top: 15px;
        opacity: 0.7;
    }
    .swipe-hint svg {
        width: 16px !important;
        height: 16px !important;
        flex-shrink: 0; 
        color: var(--zarco-red);
        animation: swipePulse 1.5s infinite ease-in-out;
    }
    @keyframes swipePulse {
        0%, 100% { opacity: 0.4; }
        50% { opacity: 1; }
    }

    .cards-container { 
        display: flex;
        flex-direction: row; 
        flex-wrap: nowrap;
        gap: 20px; 
        overflow-x: auto;
        overflow-y: hidden;
        scroll-snap-type: x mandatory;
        padding: 10px 5%;
        -ms-overflow-style: none;
        scrollbar-width: none;
        -webkit-overflow-scrolling: touch;
    }
    .cards-container::-webkit-scrollbar { display: none; }

    .category-card { 
        flex: 0 0 80vw; 
        height: 450px; 
        scroll-snap-align: center; 
    }

    .card-action {
        opacity: 1;
        transform: translateY(0);
        background: var(--white);
        color: var(--zarco-blue);
        justify-content: center;
        width: 100%;
        margin-top: 15px;
    }

    .product-categories-section { padding: 20px 0 30px; }
    .prod-cats-container {
        display: flex;
        flex-direction: row; 
        flex-wrap: nowrap;
        gap: 15px; 
        overflow-x: auto;
        overflow-y: hidden;
        scroll-snap-type: x mandatory;
        padding: 10px 5%;
        -ms-overflow-style: none;
        scrollbar-width: none;
        -webkit-overflow-scrolling: touch;
    }
    .prod-cats-container::-webkit-scrollbar { display: none; }

    .prod-cat-card {
        flex: 0 0 75vw; 
        scroll-snap-align: center;
        align-items: center;
        gap: 8px;
    }
    .prod-cat-title { font-size: 1.1rem; text-align: center; width: 100%; margin-top: 0;}

    .brands-section { padding: 20px 0 40px; display: block; overflow: hidden; }
    .brands-header { padding: 0 5%; margin-bottom: 1rem; text-align: center; }
    .brands-title { font-size: 1.3rem; margin-bottom: 0;}

    .brands-container.grid-4x2 { 
        display: flex;
        flex-direction: row !important; 
        flex-wrap: nowrap;
        gap: 15px; 
        overflow-x: auto; 
        overflow-y: hidden;
        scroll-snap-type: x mandatory; 
        overscroll-behavior-x: contain;
        padding: 10px 5%;
        -ms-overflow-style: none; 
        scrollbar-width: none; 
        align-items: center; 
        -webkit-overflow-scrolling: touch; 
        touch-action: pan-x; 
    }
    .brands-container.grid-4x2::-webkit-scrollbar { display: none; }

    .grid-4x2 .brand-card { 
        flex: 0 0 65vw; 
        background: transparent;
        scroll-snap-align: center; 
        display: block;
    }

    .grid-4x2 .brand-card img { 
        width: 100%; 
        height: auto; 
        object-fit: contain; 
        display: block;
        border-radius: 10px; 
        padding: 0; 
    }

    .secondary-slider { margin-top: 20px; margin-bottom: 50px; }
}


  :root {
    --zarco-blue: #0A2240;
    --zarco-blue-light: #16365C;
    --zarco-blue-glass: rgba(10,34,64,0.95);
    --zarco-red: #A81200;
    --white: #FFFFFF;
    --wa-green: #10B981;
    --transition-fast: 0.3s cubic-bezier(0.16,1,0.3,1);
    --shadow-pop: 0 15px 35px -5px rgba(10,34,64,0.15),0 5px 15px rgba(0,0,0,0.05)
  }
  .desktop-only { display: block }
  .mobile-only { display: none }
  .navbar {
    position: fixed;
    top: 0;
    width: 100%;
    z-index: 2000;
    transition: transform .6s var(--transition-fast),box-shadow .6s var(--transition-fast);
    box-shadow: 0 4px 20px rgba(0,0,0,.15);
    font-family: 'Inter',sans-serif
  }
  .navbar.nav-hidden { transform: translateY(-100%) }
  .nav-container {
    width: 90%;
    max-width: 1400px;
    margin: 0 auto;
    position: relative
  }
  .nav-top {
    background-color: var(--zarco-blue-light);
    padding: 20px 0;
    transition: padding var(--transition-fast)
  }
  .top-container {
    display: grid;
    grid-template-columns: 1fr auto 1fr;
    align-items: center;
    max-width: 1200px;
    margin: 0 auto
  }
  .nav-left { justify-self: start }
  .nav-center { justify-self: center }
  .nav-right {
    justify-self: end;
    display: flex;
    align-items: center;
    gap: 15px
  }
  .nav-logo img {
    height: 100px;
    filter: drop-shadow(0 4px 10px rgba(0,0,0,.3));
    transition: height var(--transition-fast);
    display: block
  }
  .nav-logo img:hover { transform: scale(1.03) }
  .nav-gif {
    height: 100px;
    object-fit: contain;
    border-radius: 8px;
    display: block;
    filter: drop-shadow(0 4px 10px rgba(0,0,0,.2))
  }
  .btn-primary {
    background-color: var(--zarco-red);
    color: var(--white);
    border: none;
    padding: 14px 32px;
    font-weight: 900;
    font-size: .85rem;
    text-transform: uppercase;
    letter-spacing: 2px;
    cursor: pointer;
    border-radius: 6px;
    transition: all var(--transition-fast);
    position: relative;
    overflow: hidden;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px
  }
  .btn-primary:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 25px rgba(168,18,0,.4);
    background-color: #ba1400
  }
  .nav-bottom {
    background-color: var(--zarco-blue);
    height: 45px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative
  }
  .bottom-container {
    display: flex;
    justify-content: center;
    align-items: center;
    width: 100%;
    position: static
  }
  .nav-menu {
    display: flex;
    list-style: none;
    gap: 4rem;
    margin: 0 auto;
    align-items: center;
    position: static;
    padding: 0
  }
  .nav-link {
    color: rgba(255,255,255,.85);
    text-decoration: none;
    font-weight: 700;
