let currentUserGlobal=null;
document.addEventListener('DOMContentLoaded',()=>{
  setupScrollAndMenu();
  setupGlobalAuth()
});

function setupScrollAndMenu(){
  let lastScrollTop=window.scrollY||document.documentElement.scrollTop;
  const navbar=document.getElementById('main-nav');
  const hamburgerBtn=document.getElementById('hamburger-btn');
  const mobileDrawer=document.getElementById('mobile-drawer');
  const drawerOverlay=document.getElementById('drawer-overlay');
  const mobileLinks=document.querySelectorAll('.mobile-link, .mobile-nav-close');

  window.addEventListener('scroll',function(){
    let scrollTop=window.scrollY||document.documentElement.scrollTop;
    if(mobileDrawer&&mobileDrawer.classList.contains('active'))return;
    if(navbar){
      if(scrollTop>80)navbar.classList.add('scrolled');
      else navbar.classList.remove('scrolled');
      if(scrollTop>250&&scrollTop>lastScrollTop)navbar.classList.add('nav-hidden');
      else navbar.classList.remove('nav-hidden')
    }
    lastScrollTop=Math.max(0,scrollTop)
  },{passive:!0});

  function toggleMenu(){
    if(hamburgerBtn)hamburgerBtn.classList.toggle('active');
    if(mobileDrawer)mobileDrawer.classList.toggle('active');
    if(drawerOverlay)drawerOverlay.classList.toggle('active');
    if(mobileDrawer&&mobileDrawer.classList.contains('active'))document.body.style.overflow='hidden';
    else document.body.style.overflow=''
  }

  if(hamburgerBtn)hamburgerBtn.addEventListener('click',toggleMenu);
  if(drawerOverlay)drawerOverlay.addEventListener('click',toggleMenu);
  if(mobileLinks)mobileLinks.forEach(link=>link.addEventListener('click',toggleMenu));

  const prodToggle=document.getElementById('mobile-prod-toggle');
  const prodMenu=document.getElementById('mobile-prod-menu');
  if(prodToggle&&prodMenu){
    prodToggle.addEventListener('click',function(){
      this.classList.toggle('open');
      if(this.classList.contains('open'))prodMenu.style.maxHeight=prodMenu.scrollHeight+"px";
      else prodMenu.style.maxHeight="0px"
    })
  }
}

function setupGlobalAuth(){
  const authTriggers=document.querySelectorAll('.auth-trigger');
  const authModal=document.getElementById('globalAuthModal');
  const desktopDropdown=document.getElementById('desktopUserDropdown');
  const closeBtns=document.querySelectorAll('.close-modal-btn');
  const btnLogouts=document.querySelectorAll('.global-logout-btn');
  const savedUser=localStorage.getItem('zarcoUser');

  if(savedUser){
    currentUserGlobal=JSON.parse(savedUser);
    updateNavbarUIGlobal(currentUserGlobal)
  } else {
    initGoogleAuthGlobal();
    document.getElementById('drawerUnauth').style.display='block';
    document.getElementById('drawerAuth').classList.remove('active')
  }

  authTriggers.forEach(btn=>{
    btn.addEventListener('click',(e)=>{
      e.preventDefault();
      e.stopPropagation();
      if(currentUserGlobal){
        if(btn.id==='desktopUserBtn'){
          desktopDropdown.classList.toggle('active')
        }
      } else {
        authModal.classList.remove('hidden');
        document.getElementById('mobile-drawer').classList.remove('active');
        document.getElementById('drawer-overlay').classList.remove('active');
        if(document.getElementById('hamburger-btn'))document.getElementById('hamburger-btn').classList.remove('active');
        document.body.style.overflow=''
      }
    })
  });

  document.addEventListener('click',(e)=>{
    if(desktopDropdown&&desktopDropdown.classList.contains('active')){
      if(!desktopDropdown.contains(e.target)&&!e.target.closest('#desktopUserBtn')){
        desktopDropdown.classList.remove('active')
      }
    }
  });

  closeBtns.forEach(btn=>{
    btn.addEventListener('click',(e)=>{
      e.target.closest('.saas-modal-overlay').classList.add('hidden')
    })
  });

  window.addEventListener('click',(e)=>{
    if(e.target.classList.contains('saas-modal-overlay')){
      e.target.classList.add('hidden')
    }
  });

  btnLogouts.forEach(btn=>{
    btn.addEventListener('click',()=>{
      localStorage.removeItem('zarcoUser');
      currentUserGlobal=null;
      document.querySelectorAll('.auth-trigger').forEach(el=>{
        el.classList.remove('logged-in')
      });
      if(desktopDropdown)desktopDropdown.classList.remove('active');
      document.getElementById('drawerUnauth').style.display='block';
      document.getElementById('drawerAuth').classList.remove('active');
      showGlobalToast("Sesión cerrada correctamente");
      initGoogleAuthGlobal();
      if(window.location.pathname.includes('perfil')){
        setTimeout(()=>{window.location.href='/'},1000)
      }
    })
  })
}

function initGoogleAuthGlobal(){
  if(typeof google==='undefined'||!google.accounts){
    void 0;
    return
  }
  const GOOGLE_CLIENT_ID='655792493975-nji5od4bj90955qdesbi3ls5l0o3hpe9.apps.googleusercontent.com';
  google.accounts.id.initialize({
    client_id:GOOGLE_CLIENT_ID,
    callback:handleCredentialResponseGlobal
  });
  const buttonContainer=document.getElementById("googleButtonContainer");
  if(buttonContainer){
    google.accounts.id.renderButton(buttonContainer,{
      theme:"outline",
      size:"large",
      text:"continue_with",
      shape:"rectangular",
      width:"350"
    })
  }
}

function handleCredentialResponseGlobal(response){
  const responsePayload=decodeJwtResponseGlobal(response.credential);
  currentUserGlobal={
    name:responsePayload.name,
    email:responsePayload.email,
    picture:responsePayload.picture
  };
  localStorage.setItem('zarcoUser',JSON.stringify(currentUserGlobal));
  localStorage.setItem('googleName',currentUserGlobal.name);
  localStorage.setItem('googleEmail',currentUserGlobal.email);
  localStorage.setItem('googlePic',currentUserGlobal.picture);
  document.getElementById('globalAuthModal').classList.add('hidden');
  updateNavbarUIGlobal(currentUserGlobal);
  showGlobalToast(`¡Bienvenido a El Zarco, ${currentUserGlobal.name.split(' ')[0]}!`)
}

function decodeJwtResponseGlobal(token){
  let base64Url=token.split('.')[1];
  let base64=base64Url.replace(/-/g,'+').replace(/_/g,'/');
  let jsonPayload=decodeURIComponent(atob(base64).split('').map(function(c){
    return'%'+('00'+c.charCodeAt(0).toString(16)).slice(-2)
  }).join(''));
  return JSON.parse(jsonPayload)
}

function updateNavbarUIGlobal(user){
  const desktopBtn=document.getElementById('desktopUserBtn');
  if(desktopBtn){
    desktopBtn.classList.add('logged-in');
    const img=desktopBtn.querySelector('.nav-avatar-img');
    if(img)img.src=user.picture
  }
  const ddName=document.querySelector('.popover-name');
  const ddEmail=document.querySelector('.popover-email');
  if(ddName)ddName.innerText=user.name;
  if(ddEmail)ddEmail.innerText=user.email;
  document.getElementById('drawerUnauth').style.display='none';
  document.getElementById('drawerAuth').classList.add('active');
  const dImg=document.getElementById('drawerAvatarImg');
  const dName=document.getElementById('drawerUserName');
  const dEmail=document.getElementById('drawerUserEmail');
  if(dImg)dImg.src=user.picture;
  if(dName)dName.innerText=user.name;
  if(dEmail)dEmail.innerText=user.email
}

function showGlobalToast(message){
  const container=document.getElementById('toast-container');
  if(!container)return;
  const toast=document.createElement('div');
  toast.className='toast';
  toast.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg> <span>${message}</span>`;
  container.appendChild(toast);
  setTimeout(()=>{toast.classList.add('fade-out')},2500);
  setTimeout(()=>{toast.remove()},2900)
}

document.addEventListener('DOMContentLoaded', () => {
    function revealAnimations() {
        const reveals = document.querySelectorAll('.reveal, .reveal-up');

        if (!('IntersectionObserver' in window)) {
            reveals.forEach(reveal => reveal.classList.add('active'));
            return;
        }

        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('active');
                }
            });
        }, { 
            threshold: 0.1, 
            rootMargin: "0px 0px -50px 0px" 
        });

        reveals.forEach(reveal => observer.observe(reveal));
    }

    revealAnimations();
});

let currentUserGlobal = null;

document.addEventListener('DOMContentLoaded', () => {
    setupGlobalAuth();
});

function setupGlobalAuth() {
    const authTriggers = document.querySelectorAll('.auth-trigger');
    const authModal = document.getElementById('globalAuthModal');
    const profileModal = document.getElementById('globalProfileModal');
    const closeBtns = document.querySelectorAll('.close-modal-btn');
    const btnLogout = document.getElementById('btnLogoutGlobal');
    const btnReorder = document.getElementById('btnReorderGlobal');

    // 1. Revisar si hay usuario guardado
    const savedUser = localStorage.getItem('zarcoUser');
    if (savedUser) {
        currentUserGlobal = JSON.parse(savedUser);
        updateUIWithUserGlobal(currentUserGlobal);
    } else {
        initGoogleAuthGlobal();
    }

    // 2. Abrir Modales
    authTriggers.forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.preventDefault();
            if(currentUserGlobal) {
                profileModal.classList.remove('hidden');
            } else {
                authModal.classList.remove('hidden');
            }
        });
    });

    // 3. Cerrar Modales
    closeBtns.forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.target.closest('.saas-modal-overlay').classList.add('hidden');
        });
    });
    window.addEventListener('click', (e) => {
        if (e.target.classList.contains('saas-modal-overlay')) {
            e.target.classList.add('hidden');
        }
    });

    // 4. Cerrar Sesión
    if(btnLogout) {
        btnLogout.addEventListener('click', () => {
            localStorage.removeItem('zarcoUser');
            currentUserGlobal = null;

            document.querySelectorAll('.auth-trigger').forEach(el => {
                el.classList.remove('logged-in');
                const img = el.querySelector('.nav-user-avatar');
                if(img) img.remove();
            });

            profileModal.classList.add('hidden');
            showGlobalToast("Sesión cerrada correctamente");
            initGoogleAuthGlobal();
        });
    }

    // 5. Botón Cargar Pedido (Te lleva a Catálogo y carga los items)
    if(btnReorder) {
        btnReorder.addEventListener('click', () => {
            profileModal.classList.add('hidden');

            // Si ya estamos en el catálogo, llamamos a la función local si existe
            if(window.location.pathname.includes('catalogo')) {
                if(typeof window.triggerDemoReorder === 'function') {
                    window.triggerDemoReorder();
                } else {
                    showGlobalToast("Abre el catálogo para usar esta función.");
                }
            } else {
                // Si estamos en Inicio o Nosotros, redirigimos al catálogo con un flag
                localStorage.setItem('zarcoPendingReorder', 'true');
                window.location.href = '/catalogo'; // Cambia esto si el link de tu catálogo en webflow es diferente
            }
        });
    }
}

// INICIALIZADOR DE GOOGLE CON TU LLAVE
function initGoogleAuthGlobal() {
    if (typeof google === 'undefined' || !google.accounts) {
        void 0; // Reintenta si no ha cargado
        return;
    }

    // ¡AQUÍ ESTÁ TU LLAVE REAL!
    const GOOGLE_CLIENT_ID = '655792493975-nji5od4bj90955qdesbi3ls5l0o3hpe9.apps.googleusercontent.com';

    google.accounts.id.initialize({
        client_id: GOOGLE_CLIENT_ID,
        callback: handleCredentialResponseGlobal
    });

    const buttonContainer = document.getElementById("googleButtonContainer");
