function handleCredentialResponseGlobal(response) {
    const responsePayload = decodeJwtResponseGlobal(response.credential);

    currentUserGlobal = {
        name: responsePayload.name,
        email: responsePayload.email,
        picture: responsePayload.picture
    };

    localStorage.setItem('zarcoUser', JSON.stringify(currentUserGlobal));

    document.getElementById('globalAuthModal').classList.add('hidden');
    updateUIWithUserGlobal(currentUserGlobal);
    showGlobalToast(`Bienvenido, ${currentUserGlobal.name}`);
}

function decodeJwtResponseGlobal(token) {
    let base64Url = token.split('.')[1];
    let base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
    let jsonPayload = decodeURIComponent(atob(base64).split('').map(function(c) {
        return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
    }).join(''));
    return JSON.parse(jsonPayload);
}

function updateUIWithUserGlobal(user) {
    document.querySelectorAll('.auth-trigger').forEach(el => {
        el.classList.add('logged-in');
        if (!el.querySelector('.nav-user-avatar')) {
            el.innerHTML += `<img src="${user.picture}" class="nav-user-avatar" alt="Perfil" referrerpolicy="no-referrer">`;
        } else {
            el.querySelector('.nav-user-avatar').src = user.picture;
        }
    });

    const modalAvatar = document.getElementById('userAvatarGlobal');
    const modalName = document.getElementById('userNameDisplayGlobal');
    const modalEmail = document.getElementById('userEmailDisplayGlobal');

    if(modalAvatar) modalAvatar.src = user.picture;
    if(modalName) modalName.innerText = user.name;
    if(modalEmail) modalEmail.innerText = user.email;
