    toast.className = 'toast';
    toast.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg> ${message}`;
    container.appendChild(toast);
    setTimeout(() => { toast.classList.add('fade-out'); }, 2000);
    setTimeout(() => { toast.remove(); }, 2400);
